    rxd = 1'b0;
    wait_clks(BIT_CLOCKS);
    // 8 data bits
    for (int i = 0; i < 8; i++) begin
      rxd = b[i];
      wait_clks(BIT_CLOCKS);
    end
    // stop bit
    rxd = 1'b1;
    wait_clks(BIT_CLOCKS);
  endtask

  // Simple reset sequence
